-- Generated presentation records: 109 people (102 students, 7 teachers).
-- Run supabase_presentation_people.sql first. This script upserts only batch thesis-presentation-2026-09.
begin;
on conflict (id) do update set
  display_name = excluded.display_name,
  avatar_url = excluded.avatar_url,
  total_score = excluded.total_score,
  week_start = excluded.week_start,
  weekly_map_score = excluded.weekly_map_score,
  weekly_pvp_score = excluded.weekly_pvp_score,
  pvp_wins = excluded.pvp_wins,
  pvp_losses = excluded.pvp_losses,
  completed_lessons = excluded.completed_lessons,
  last_active_at = excluded.last_active_at
where public.presentation_people.batch_id = 'thesis-presentation-2026-09';
on conflict do nothing;
do $$
begin
  if (select count(*) from public.presentation_people where batch_id = 'thesis-presentation-2026-09') <> 109 then
    raise exception 'Presentation batch count mismatch';
  end if;
  if exists (select 1 from public.presentation_people where batch_id = 'thesis-presentation-2026-09' and role = 'student' and weekly_pvp_score <> pvp_wins * 100) then
    raise exception 'Presentation PvP score mismatch';
  end if;
end $$;
commit;

select grade, role, count(*) as people, count(*) filter (where weekly_pvp_score > 0) as pvp_ranked
from public.presentation_people where batch_id = 'thesis-presentation-2026-09' group by grade, role order by grade, role;
